// Desbloqueo de audio para iOS: se debe llamar de forma SÍNCRONA dentro del
// propio manejador de clic (antes de cualquier setTimeout), para que Safari
// asocie la reproducción de audio (aunque llegue con un pequeño retraso) con
// el toque real del usuario y no la bloquee.
function unlockAudioTap() {
  try {
    const silentAudio = new Audio("data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA=");
    silentAudio.volume = 0;
    silentAudio.play().catch(() => {});
  } catch (e) {}
  try {
    const u = new SpeechSynthesisUtterance("");
    u.volume = 0;
    window.speechSynthesis.speak(u);
  } catch (e) {}
}

// ---- Voz clonada (ElevenLabs) ----
// Llama al endpoint serverless /api/tts (que vive fuera de este componente, en Vercel)
// donde se guarda la API key de ElevenLabs de forma segura y se usa tu Voice ID clonado.
// Si el endpoint no existe o falla (por ejemplo, corriendo en el preview de Claude.ai,
// donde no hay backend), devuelve false y el que llama usa la voz nativa del navegador
// (SpeechSynthesisUtterance) como respaldo automático.
let _elevenAudio = null;
// Configuración global del locutor (volumen / silencio), persistida
const ANNOUNCER_KEY = "losmalucos-announcer";
let announcerSettings = { volume: 100, muted: false };
try {
  const saved = JSON.parse(localStorage.getItem(ANNOUNCER_KEY) || "{}");
  if (typeof saved.volume === "number") announcerSettings.volume = saved.volume;
  if (typeof saved.muted === "boolean") announcerSettings.muted = saved.muted;
} catch (e) {}

function saveAnnouncerSettings() {
  try { localStorage.setItem(ANNOUNCER_KEY, JSON.stringify(announcerSettings)); } catch (e) {}
}

function setAnnouncerVolume(v) {
  announcerSettings.volume = v;
  saveAnnouncerSettings();
  if (_elevenAudio) { try { _elevenAudio.volume = v / 100; } catch (e) {} }
}

function setAnnouncerMuted(m) {
  announcerSettings.muted = m;
  saveAnnouncerSettings();
  if (m && _elevenAudio) { try { _elevenAudio.pause(); } catch (e) {} }
  if (m) { try { window.speechSynthesis.cancel(); } catch (e) {} }
}

async function elevenSpeak(text, onEnd) {
  if (announcerSettings.muted) {
    if (onEnd) onEnd();
    return true;
  }
  try {
    const res = await fetch("/api/tts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text }),
    });
    if (!res.ok) return false;
    const blob = await res.blob();
    if (!blob || blob.size === 0) return false;
    const url = URL.createObjectURL(blob);
    if (_elevenAudio) {
      try { _elevenAudio.pause(); } catch (e) {}
    }
    _elevenAudio = new Audio(url);
    _elevenAudio.volume = announcerSettings.volume / 100;
    if (onEnd) _elevenAudio.onended = onEnd;
    await _elevenAudio.play();
    return true;
  } catch (e) {
    return false;
  }
}

// Helper para dibujar rectángulos redondeados en canvas
function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

