function MuteButton({ corner = "right" }) {
  const [muted, setMuted] = useState(announcerSettings.muted);
  const toggleMute = () => {
    const next = !muted;
    setMuted(next);
    setAnnouncerMuted(next);
  };
  return (
    <button onClick={toggleMute} style={{
      position: "absolute", bottom: 8, [corner]: 8, zIndex: 5,
      background: "#0a0a0a", border: "1px solid #FFD700",
      borderRadius: 999, width: 30, height: 30,
      fontSize: 14, color: "#FFD700", cursor: "pointer",
      boxShadow: "0 0 10px #FFD70066",
      display: "flex", alignItems: "center", justifyContent: "center",
    }}>{muted ? "🔇" : "🔊"}</button>
  );
}

function VolumeButton({ corner = "left" }) {
  const [volume, setVolume] = useState(announcerSettings.volume);
  const [open, setOpen] = useState(false);
  const changeVolume = (v) => {
    setVolume(v);
    setAnnouncerVolume(v);
  };
  return (
    <div style={{ position: "absolute", bottom: 8, [corner]: 8, zIndex: 5, display: "flex", alignItems: "center", gap: 4 }}>
      <button onClick={() => setOpen(o => !o)} style={{
        background: "#0a0a0a", border: "1px solid #FFD700",
        borderRadius: 999, width: 30, height: 30,
        fontSize: 13, color: "#FFD700", cursor: "pointer",
        boxShadow: "0 0 10px #FFD70066",
        display: "flex", alignItems: "center", justifyContent: "center",
        flexShrink: 0,
      }}>🎚️</button>
      {open && (
        <div style={{
          background: "#0a0a0a", border: "1px solid #FFD70088",
          borderRadius: 999, padding: "3px 8px",
          display: "flex", alignItems: "center", gap: 5,
        }}>
          <input
            type="range" min={0} max={100} value={volume}
            onChange={(e) => changeVolume(Number(e.target.value))}
            style={{ width: 60, accentColor: "#FFD700" }}
          />
          <span style={{ fontSize: 9, color: "#FFD700", fontFamily: "'Orbitron', sans-serif", minWidth: 20 }}>{volume}</span>
        </div>
      )}
    </div>
  );
}


function GameScreen({ team1, team2, meta, initialState, onReset, onRevanche, roundCycle = 4, players = [], isRevancha = false }) {
  const [scores, setScores] = useState(isRevancha ? [99, 99] : (initialState?.scores || [0, 0]));
  const [inputs, setInputs] = useState(["", ""]);
  const [history, setHistory] = useState(initialState?.history || []);
  const [winner, setWinner] = useState(initialState?.winner ?? null);
  const [loserScore, setLoserScore] = useState(initialState?.loserScore ?? null);
  const [showConfetti, setShowConfetti] = useState(false);
  const [matchHistory, setMatchHistory] = useState(() => {
    try { return JSON.parse(localStorage.getItem("losmalucos-matches") || "[]"); } catch(e) { return []; }
  });

  const tc = TEAM_COLORS;
  const names = [team1, team2];

  // Efecto slot al hacer revancha
  useEffect(() => {
    if (!isRevancha) return;
    const t = setTimeout(() => setScores([0, 0]), 120);
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    saveGame({ t1: team1, t2: team2, meta, scores, history, winner, loserScore });
  }, [scores, history, winner, loserScore]);

  const speak = (text) => {
    elevenSpeak(text).then((ok) => {
      if (ok) return;
      if (announcerSettings.muted) return;
      if (!window.speechSynthesis) return;
      window.speechSynthesis.cancel();
      setTimeout(() => {
        const utter = new SpeechSynthesisUtterance(text);
        utter.lang = "es-MX"; utter.rate = 0.88; utter.pitch = 0.5; utter.volume = announcerSettings.volume / 100;
        const go = () => {
          const voices = window.speechSynthesis.getVoices();
          const male = voices.find(v => v.lang.startsWith("es") && v.name.toLowerCase().includes("jorge"))
            || voices.find(v => v.lang === "es-MX") || voices.find(v => v.lang.startsWith("es"));
          if (male) utter.voice = male;
          window.speechSynthesis.speak(utter);
        };
        if (window.speechSynthesis.getVoices().length > 0) go();
        else window.speechSynthesis.onvoiceschanged = go;
      }, 150);
    });
  };

  // Habla una lista de frases en orden, esperando que cada una termine antes de decir la siguiente
  const speakSequence = (texts) => {
    if (announcerSettings.muted) return;
    if (!window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const queue = [...texts];
    // Une todas las frases en un solo pedido a ElevenLabs para que salga
    // como un audio continuo, sin pausas entre frase y frase.
    const combined = queue.filter(Boolean).join(". ");
    elevenSpeak(combined).then((ok) => {
      if (ok) return;
      // Respaldo: voz nativa del navegador, frase por frase
      const fallbackQueue = [...texts];
      const speakNext = () => {
        const text = fallbackQueue.shift();
        if (!text) return;
        const utter = new SpeechSynthesisUtterance(text);
        utter.lang = "es-MX"; utter.rate = 0.88; utter.pitch = 0.5; utter.volume = announcerSettings.volume / 100;
        const voices = window.speechSynthesis.getVoices();
        const male = voices.find(v => v.lang.startsWith("es") && v.name.toLowerCase().includes("jorge"))
          || voices.find(v => v.lang === "es-MX") || voices.find(v => v.lang.startsWith("es"));
        if (male) utter.voice = male;
        utter.onend = () => speakNext();
        utter.onerror = () => speakNext();
        window.speechSynthesis.speak(utter);
      };
      setTimeout(() => {
        if (window.speechSynthesis.getVoices().length > 0) speakNext();
        else window.speechSynthesis.onvoiceschanged = speakNext;
      }, 150);
    });
  };

  const playSound = (type) => {
    if (announcerSettings.muted) return;
    try {
      const ctx = getAudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      if (type === "point") {
        osc.frequency.setValueAtTime(520, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(780, ctx.currentTime + 0.12);
        gain.gain.setValueAtTime(0.3, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.2);
        osc.start(); osc.stop(ctx.currentTime + 0.2);
      } else if (type === "tie") {
        osc.type = "triangle";
        osc.frequency.setValueAtTime(400, ctx.currentTime);
        osc.frequency.setValueAtTime(300, ctx.currentTime + 0.15);
        gain.gain.setValueAtTime(0.2, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
        osc.start(); osc.stop(ctx.currentTime + 0.3);
      } else if (type === "win") {
        // Fanfarria triunfal: melodía principal ascendente + armonía + acorde final
        const melody = [392, 523, 659, 784, 1046]; // G4 C5 E5 G5 C6
        melody.forEach((freq, idx) => {
          const o = ctx.createOscillator(); const g = ctx.createGain();
          o.connect(g); g.connect(ctx.destination);
          o.type = idx === melody.length - 1 ? "square" : "triangle";
          o.frequency.value = freq;
          const t = ctx.currentTime + idx * 0.13;
          const dur = idx === melody.length - 1 ? 0.5 : 0.16;
          g.gain.setValueAtTime(0.28, t);
          g.gain.exponentialRampToValueAtTime(0.001, t + dur);
          o.start(t); o.stop(t + dur);
        });
        // Armonía de fondo (acorde mayor sostenido)
        [523, 659, 784].forEach((freq) => {
          const o = ctx.createOscillator(); const g = ctx.createGain();
          o.connect(g); g.connect(ctx.destination);
          o.type = "sine";
          o.frequency.value = freq;
          const t = ctx.currentTime + 0.55;
          g.gain.setValueAtTime(0.0001, t);
          g.gain.linearRampToValueAtTime(0.18, t + 0.05);
          g.gain.exponentialRampToValueAtTime(0.001, t + 0.9);
          o.start(t); o.stop(t + 0.9);
        });
        // Golpe final tipo "ta-da!"
        setTimeout(() => {
          try {
            const ctx2 = getAudioCtx();
            [1046, 1318].forEach((freq, idx) => {
              const o = ctx2.createOscillator(); const g = ctx2.createGain();
              o.connect(g); g.connect(ctx2.destination);
              o.type = "square";
              o.frequency.value = freq;
              g.gain.setValueAtTime(0.22, ctx2.currentTime);
              g.gain.exponentialRampToValueAtTime(0.001, ctx2.currentTime + 0.35);
              o.start(); o.stop(ctx2.currentTime + 0.35);
            });
          } catch(e) {}
        }, 700);
      } else if (type === "zapato") {
        osc.type = "sawtooth";
        osc.frequency.setValueAtTime(200, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(80, ctx.currentTime + 0.4);
        gain.gain.setValueAtTime(0.3, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
        osc.start(); osc.stop(ctx.currentTime + 0.4);
      }
    } catch(e) {}
  };

  const chamo = () => Math.random() > 0.5 ? ", mis panas." : ".";
  const vale = () => Math.random() > 0.5 ? ", muchachos." : ".";

  const frasesPocoPuntaje = (nombre, pts, plural = false) => {
    const f = plural ? [
      "Es mejor coger " + pts + " que " + pts + " cojan a uno. " + nombre + " anotaron " + pts + " puntos" + chamo(),
      "Algo es algo. " + nombre + " se llevaron " + pts + " puntitos. Es mejor coger " + pts + " que " + pts + " cojan a uno" + vale(),
    ] : [
      "Es mejor coger " + pts + " que " + pts + " cojan a uno. " + nombre + " anoto " + pts + " puntos" + chamo(),
      "Algo es algo. " + nombre + " se llevo " + pts + " puntitos. Es mejor coger " + pts + " que " + pts + " cojan a uno" + vale(),
    ];
    return f[Math.floor(Math.random() * f.length)];
  };

  const frasesPunto = (nombre, pts, total, plural = false) => {
    const f = plural ? [
      "Muy bien! " + nombre + " anotaron " + pts + " puntos. Van " + total + " en total" + chamo(),
      "Asi se juega! " + nombre + " sumaron " + pts + ". Llevan " + total + " puntos" + vale(),
      "Brutal! " + nombre + " se apuntaron " + pts + " punticos. Total acumulado " + total + chamo(),
      "Ahi estan! " + nombre + " con " + pts + " puntos. Acumulan " + total + vale(),
    ] : [
      "Muy bien! " + nombre + " anoto " + pts + " puntos. Lleva " + total + " en total" + chamo(),
      "Asi se juega! " + nombre + " suma " + pts + ". Acumula " + total + " puntos" + vale(),
      "Brutal! " + nombre + " se apunto " + pts + " punticos. Total acumulado " + total + chamo(),
      "Ahi esta! " + nombre + " con " + pts + " puntos. Lleva " + total + " acumulado" + vale(),
    ];
    return f[Math.floor(Math.random() * f.length)];
  };

  const frasesEmpate = (pts) => {
    const f = [
      "Empate! " + pts + " puntos cada uno. El marcador queda igual" + chamo(),
      "Tablas! " + pts + " a " + pts + ". No gana nadie esta ronda" + vale(),
    ];
    return f[Math.floor(Math.random() * f.length)];
  };

  const frasesGanador = (nombre, total, plural = false) => {
    const f = plural ? [
      "Llegaron los campeones! " + nombre + " ganaron la partida con " + total + " puntos. Felicitaciones" + chamo(),
      "Asi si es jugar domino! " + nombre + " se coronaron con " + total + " puntos" + vale(),
    ] : [
      "Llego el campeon! " + nombre + " gano la partida con " + total + " puntos. Felicitaciones" + chamo(),
      "Asi si es jugar domino! " + nombre + " se corono con " + total + " puntos" + vale(),
    ];
    return f[Math.floor(Math.random() * f.length)];
  };

  const frasesZapato = (ganador, perdedor, plural = false) => {
    const f = plural ? [
      ganador + " ganaron! Y " + perdedor + " se llevaron el zapato. Cero puntos! Que malos! Les toca brindar las cervezas" + chamo(),
      "Que paliza! " + ganador + " arrasaron. " + perdedor + " se fueron con el zapato puesto. Que malos! Les toca brindar las cervezas" + vale(),
    ] : [
      ganador + " gano! Y " + perdedor + " se llevo el zapato. Cero puntos! Que malo! Le toca brindar las cervezas" + chamo(),
      "Que paliza! " + ganador + " arraso. " + perdedor + " se fue con el zapato puesto. Que malo! Le toca brindar las cervezas" + vale(),
    ];
    return f[Math.floor(Math.random() * f.length)];
  };

  const playClick = () => {
    if (announcerSettings.muted) return;
    try {
      const ctx = getAudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "square";
      osc.frequency.setValueAtTime(600 + Math.random() * 200, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.05);
      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.06);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(ctx.currentTime); osc.stop(ctx.currentTime + 0.06);
    } catch(e) {}
  };

  const addPoints = (i) => {
    const pts = parseInt(inputs[i]);
    if (isNaN(pts) || pts <= 0) return;
    unlockAudioTap();
    const newScores = scores.map((s, idx) => idx === i ? s + pts : s);
    const roundsPlayed = history.length;
    setHistory([...history, { round: (roundsPlayed % roundCycle) + 1, added: [i === 0 ? pts : 0, i === 1 ? pts : 0], totals: [...newScores], tie: false }]);
    const newWinner = newScores[i] >= meta ? i : null;
    setScores(newScores);
    setInputs(["", ""]);
    if (newWinner !== null) {
      setWinner(newWinner);
      const loser = newWinner === 0 ? 1 : 0;
      setLoserScore(newScores[loser]);
      setShowConfetti(true);
      // Guardar partida en historial
      const newMatch = {
        date: new Date().toLocaleDateString("es-VE"),
        winner: names[newWinner],
        loser: names[loser],
        winScore: newScores[newWinner],
        loseScore: newScores[loser],
        zapato: newScores[loser] === 0,
      };
      const updated = [...matchHistory, newMatch];
      setMatchHistory(updated);
      try { localStorage.setItem("losmalucos-matches", JSON.stringify(updated)); } catch(e) {}
      if (newScores[loser] === 0) {
        playSound("zapato");
        setTimeout(() => speakSequence([frasesZapato(names[newWinner], names[loser], roundCycle === 4)]), 1400);
      } else {
        playSound("win");
        setTimeout(() => speakSequence([frasesGanador(names[newWinner], newScores[newWinner], roundCycle === 4)]), 1400);
      }
    } else {
      playSound("point");
      const eraPrimerPuntoDeEste = scores[i] === 0;
      const elOtroYaTeniaPuntos = scores[1 - i] > 0;
      const esSegundoEnAnotar = eraPrimerPuntoDeEste && elOtroYaTeniaPuntos;
      const plural = roundCycle === 4;

      const fraseRonda = pts <= 5 ? frasesPocoPuntaje(names[i], pts, plural) : frasesPunto(names[i], pts, newScores[i], plural);
      const secuencia = [];

      if (esSegundoEnAnotar) {
        const frasesRompeHielo = plural ? [
          `${names[i]} le pusieron el numero a la casa`,
          `${names[i]} rayaron`,
        ] : [
          `${names[i]} le puso el numero a la casa`,
          `${names[i]} rayó`,
        ];
        secuencia.push(frasesRompeHielo[Math.floor(Math.random() * frasesRompeHielo.length)]);
      }

      secuencia.push(fraseRonda);

      const cercaDeMeta = newScores.some((s) => {
        const restante = meta - s;
        return restante <= 5 && restante > 0;
      });
      if (cercaDeMeta) {
        secuencia.push("Todavía no se va");
      }

      const todosCercaDeMeta = newScores.every((s) => {
        const restante = meta - s;
        return restante <= 10 && restante > 0;
      });
      if (todosCercaDeMeta) {
        secuencia.push("Aqui cualquier culo echa sangre");
      }

      if (roundsPlayed >= 0) {
        const nextPlayer = ((roundsPlayed + 1) % roundCycle) + 1;
        const nextName = players[nextPlayer - 1] || `Jugador ${nextPlayer}`;
        secuencia.push(`Sale ${nextName}`);
      }

      setTimeout(() => speakSequence(secuencia), 800);
    }
  };

  const registerTie = () => {
    const pts0 = parseInt(inputs[0]);
    const pts1 = parseInt(inputs[1]);
    if (isNaN(pts0) || isNaN(pts1) || pts0 <= 0 || pts1 <= 0) return;
    const roundsPlayed = history.length;
    setHistory([...history, { round: (roundsPlayed % roundCycle) + 1, added: [pts0, pts1], totals: [...scores], tie: true }]);
    setInputs(["", ""]);
    playSound("tie");
    const secuencia = [frasesEmpate(pts0)];
    if (roundsPlayed >= 0) {
      const nextPlayer = ((roundsPlayed + 1) % roundCycle) + 1;
      const nextName = players[nextPlayer - 1] || `Jugador ${nextPlayer}`;
      secuencia.push(`Sale ${nextName}`);
    }
    speakSequence(secuencia);
  };

  const handleAskPlayer = () => {
    playClick();
    if (history.length === 0) {
      speak("Todavia no ha salido nadie" + chamo());
      return;
    }
    const currentPlayer = (history.length % roundCycle) + 1;
    const currentName = players[currentPlayer - 1] || `Jugador ${currentPlayer}`;
    speak(`Sale ${currentName}`);
  };

  const handleUndo = () => {
    if (history.length === 0 || winner !== null) return;
    const last = history[history.length - 1];
    const prevScores = scores.map((s, i) => s - last.added[i]);
    setScores(prevScores);
    setHistory(history.slice(0, -1));
    playClick();
    speak(roundCycle === 4
      ? "Espera, vamos a revertir ese punto" + chamo()
      : "Espera, vamos a revertir ese punto" + chamo()
    );
  };

  const handleReset = () => {
    try { localStorage.removeItem(STORAGE_KEY); } catch (e) {}
    setLoserScore(null); setShowConfetti(false); onReset();
  };

  const handleShareResult = async () => {
    playClick();
    try {
      const W = 1080, H = 1700;
      const canvas = document.createElement("canvas");
      canvas.width = W; canvas.height = H;
      const ctx = canvas.getContext("2d");

      // Fondo negro casino
      const grad = ctx.createRadialGradient(W/2, H*0.2, 100, W/2, H*0.2, H);
      grad.addColorStop(0, "#1a1a1a");
      grad.addColorStop(1, "#000000");
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, W, H);

      // Líneas de grid sutiles
      ctx.strokeStyle = "rgba(255,215,0,0.06)";
      ctx.lineWidth = 1;
      for (let x = 0; x < W; x += 60) { ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
      for (let y = 0; y < H; y += 60) { ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }

      // Logo: la ficha de dominó de la pantalla inicial
      const logoImg = new Image();
      logoImg.crossOrigin = "anonymous";
      await new Promise((resolve) => { logoImg.onload = resolve; logoImg.onerror = resolve; logoImg.src = WELCOME_IMAGE_BASE64; });
      const logoSize = 130;
      ctx.save();
      ctx.shadowColor = "#FFD700"; ctx.shadowBlur = 30;
      ctx.drawImage(logoImg, W/2 - logoSize/2, 60, logoSize, logoSize);
      ctx.restore();

      // Cargar fuentes Orbitron/Cinzel antes de dibujar texto
      try {
        await document.fonts.load("900 56px Cinzel");
        await document.fonts.load("900 64px Orbitron");
        await document.fonts.load("700 30px Orbitron");
        await document.fonts.ready;
      } catch (e) {}

      // Título app
      ctx.textAlign = "center";
      ctx.fillStyle = "#FFD700";
      ctx.shadowColor = "#FFD700"; ctx.shadowBlur = 18;
      ctx.font = "900 52px 'Cinzel', serif";
      ctx.fillText("DOMINÓ SCORE VENEZUELA", W/2, 250);
      ctx.shadowBlur = 0;

      // Línea decorativa
      ctx.strokeStyle = "#FFD700";
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(W*0.2, 285); ctx.lineTo(W*0.8, 285); ctx.stroke();

      const isZapato = loserScore === 0;
      const loserIdx = winner === 0 ? 1 : 0;
      const winColor = tc[winner].main;
      const loseColor = tc[loserIdx].main;

      // Helper: dibuja dos elementos (texto + emoji) centrados, uno al lado del otro
      const drawPair = (textStr, textFont, textColor, emojiStr, emojiFont, shadowColor, y) => {
        ctx.font = textFont;
        const wText = ctx.measureText(textStr).width;
        ctx.font = emojiFont;
        const wEmoji = ctx.measureText(emojiStr).width;
        const gapPx = 36;
        const totalW = wText + gapPx + wEmoji;
        const startX = W/2 - totalW/2;
        ctx.textAlign = "left";
        ctx.font = textFont;
        ctx.fillStyle = textColor;
        if (shadowColor) { ctx.shadowColor = shadowColor; ctx.shadowBlur = 18; }
        ctx.fillText(textStr, startX, y);
        ctx.shadowBlur = 0;
        ctx.font = emojiFont;
        ctx.fillText(emojiStr, startX + wText + gapPx, y);
        ctx.textAlign = "center";
      };

      // ── GANADORES ──
      ctx.font = "700 46px 'Orbitron', Arial, sans-serif";
      ctx.fillStyle = winColor;
      ctx.fillText(roundCycle === 4 ? "GANADORES" : "GANADOR", W/2, 380);

      ctx.font = "900 56px 'Orbitron', Arial, sans-serif";
      ctx.fillStyle = "#fff";
      ctx.shadowColor = winColor; ctx.shadowBlur = 16;
      ctx.fillText(names[winner].toUpperCase(), W/2, 460);
      ctx.shadowBlur = 0;

      drawPair(String(scores[winner]), "900 150px 'Orbitron', Arial, sans-serif", winColor, "🏆", "180px Arial", winColor, 720);

      // Línea divisoria
      ctx.strokeStyle = "#E8000D55";
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(W*0.25, 850); ctx.lineTo(W*0.75, 850); ctx.stroke();

      // ── PERDEDORES ──
      ctx.font = "700 46px 'Orbitron', Arial, sans-serif";
      ctx.fillStyle = loseColor;
      ctx.fillText(roundCycle === 4 ? "PERDEDORES" : "PERDEDOR", W/2, 940);

      ctx.font = "900 56px 'Orbitron', Arial, sans-serif";
      ctx.fillStyle = "#fff";
      ctx.shadowColor = loseColor; ctx.shadowBlur = 16;
      ctx.fillText(names[loserIdx].toUpperCase(), W/2, 1020);
      ctx.shadowBlur = 0;

      drawPair(String(scores[loserIdx]), "900 150px 'Orbitron', Arial, sans-serif", loseColor, isZapato ? "👟" : "😢", "180px Arial", loseColor, 1300);

      // ── A llorar pal' valle ──
      ctx.font = "700 40px 'Orbitron', Arial, sans-serif";
      ctx.fillStyle = "#ffffff";
      ctx.fillText("A LLORAR PAL’ VALLE", W/2, 1450);

      const dataUrl = canvas.toDataURL("image/png");
      if (!dataUrl || dataUrl === "data:,") { alert("toDataURL devolvió vacío"); return; }
      setShareImageUrl(dataUrl);
    } catch (e) {
      console.error("Error generando imagen:", e);
      alert("Error: " + e.name + " - " + e.message);
    }
  };

  const handleRevanche = () => {
    const frases = ["Vamos por la revancha, muchachos", "Vamos por el desquite mis panas"];
    speak(frases[Math.floor(Math.random() * frases.length)]);
    setTimeout(() => {
      try { localStorage.removeItem(STORAGE_KEY); } catch (e) {}
      setScores([0, 0]);
      setInputs(["", ""]);
      setHistory([]);
      setWinner(null);
      setLoserScore(null);
      setShowConfetti(false);
      onRevanche();
    }, 200);
  };

  const [showHistory, setShowHistory] = useState(false);
  const [shareImageUrl, setShareImageUrl] = useState(null);
  const [leadInfo, setLeadInfo] = useState({ idx: -1, diff: 0 });

  useEffect(() => {
    if (scores[0] === scores[1]) {
      setLeadInfo({ idx: -1, diff: 0 });
    } else if (scores[0] > scores[1]) {
      setLeadInfo({ idx: 0, diff: scores[0] - scores[1] });
    } else {
      setLeadInfo({ idx: 1, diff: scores[1] - scores[0] });
    }
  }, [scores[0], scores[1]]);

  return (
    <div style={{
      minHeight: "100vh",
      background: "radial-gradient(ellipse at top, #1a1a1a 0%, #000000 60%)",
      fontFamily: "'Orbitron', sans-serif",
      padding: "12px 12px 100px",
      position: "relative", overflow: "hidden",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700;900&family=Cinzel:wght@600;900&display=swap');
        * { box-sizing: border-box; }
        input::-webkit-outer-spin-button, input::-webkit-inner-spin-button { -webkit-appearance: none; }
        .add-btn:active { transform: scale(0.94) translate(3px,3px); }
        .comic-btn:active { transform: scale(0.95) translate(3px,3px); }
        @keyframes slideDown { from{opacity:0;transform:translateY(-12px)} to{opacity:1;transform:translateY(0)} }
        @keyframes comicPop { 0%{transform:scale(0.5) rotate(-8deg);opacity:0} 70%{transform:scale(1.1) rotate(2deg)} 100%{transform:scale(1) rotate(0deg);opacity:1} }
        @keyframes wobble { 0%,100%{transform:rotate(-3deg)} 50%{transform:rotate(3deg)} }
        @keyframes shoeDrop { 0%{transform:translateY(-120px) rotate(-30deg) scale(0.5);opacity:0} 60%{transform:translateY(10px) rotate(15deg) scale(1.15)} 80%{transform:translateY(-5px) rotate(-8deg) scale(1)} 100%{transform:translateY(0) rotate(0deg) scale(1);opacity:1} }
        @keyframes shoeShake { 0%,100%{transform:rotate(-6deg) scale(1)} 50%{transform:rotate(6deg) scale(1.05)} }
        @keyframes sparkPop { 0%,100%{opacity:0;transform:translateX(-50%) scale(0.6)} 50%{opacity:1;transform:translateX(-50%) scale(1.3)} }
        @keyframes bounce { 0%,100%{transform:scale(1) rotate(-5deg)} 50%{transform:scale(1.15) rotate(5deg)} }
        @keyframes pulse { 0%,100%{transform:scale(1)} 50%{transform:scale(1.04)} }
        @keyframes confettiFall { 0%{transform:translateY(-20px) rotate(0deg);opacity:1} 100%{transform:translateY(110vh) rotate(720deg);opacity:0} }
        @keyframes starSpin { 0%{transform:rotate(0deg) scale(1)} 50%{transform:rotate(180deg) scale(1.2)} 100%{transform:rotate(360deg) scale(1)} }
        @keyframes shake { 0%,100%{transform:translateX(0)} 25%{transform:translateX(-4px)} 75%{transform:translateX(4px)} }
        @keyframes neonPulse { 0%,100%{ box-shadow: 0 0 8px #FFD700, 0 0 16px #FFD70066, inset 0 0 12px #FFD70022 } 50%{ box-shadow: 0 0 16px #FFD700, 0 0 32px #FFD70099, inset 0 0 18px #FFD70044 } }
        @keyframes neonPulseGreen { 0%,100%{ box-shadow: 0 0 8px #00B800, 0 0 16px #00B80066, inset 0 0 12px #00B80022 } 50%{ box-shadow: 0 0 16px #00B800, 0 0 32px #00B80099, inset 0 0 18px #00B80044 } }
        @keyframes neonText { 0%,100%{ text-shadow: 0 0 8px #FFD700, 0 0 18px #FFD70099, 0 0 32px #FFD70055 } 50%{ text-shadow: 0 0 14px #FFD700, 0 0 28px #FFD700cc, 0 0 48px #FFD70088 } }
        @keyframes chipSpin { 0%{transform:rotate(0deg)} 100%{transform:rotate(360deg)} }
        @keyframes chipFloat { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-10px)} }
      `}</style>

      {/* Líneas de neón de fondo */}
      <div style={{
        position: "fixed", inset: 0, pointerEvents: "none", zIndex: 0,
        backgroundImage: "repeating-linear-gradient(0deg, #FFD70010 0px, transparent 1px, transparent 39px, #FFD70010 40px), repeating-linear-gradient(90deg, #FFD70010 0px, transparent 1px, transparent 39px, #FFD70010 40px)",
      }} />

      {/* Fichas de casino flotantes */}
      {[
        { left:"6%", top:"8%", size:40, delay:0, dur:4.2, color:"#FFD700" },
        { right:"5%", top:"14%", size:30, delay:1.2, dur:3.6, color:"#E8000D" },
        { left:"4%", top:"60%", size:26, delay:0.6, dur:4.8, color:"#0057D9" },
        { right:"7%", top:"66%", size:34, delay:1.8, dur:3.9, color:"#FFD700" },
      ].map((c, i) => (
        <div key={i} style={{
          position:"fixed", left:c.left, right:c.right, top:c.top,
          width:c.size, height:c.size, borderRadius:"50%",
          border:`2px dashed ${c.color}`, opacity:0.2,
          pointerEvents:"none", zIndex:0,
          animation: `chipFloat ${c.dur}s ${c.delay}s ease-in-out infinite, chipSpin ${c.dur*3}s linear infinite`,
        }} />
      ))}

      {showConfetti && <Confetti />}

      {/* ── HEADER ─────────────────────────────── */}
      <div style={{
        background: "#0a0a0a",
        border: "1px solid #FFD700",
        borderRadius: 14,
        padding: "12px 16px 16px",
        marginBottom: 12,
        textAlign: "center",
        boxShadow: "0 0 16px #FFD70044, inset 0 0 14px #00000099",
        position: "relative", zIndex: 2,
        overflow: "hidden",
      }}>
        <VolumeButton corner="left" />
        <MuteButton corner="right" />
        <button onClick={() => { unlockAudioTap(); speak(roundCycle === 4 ? "Una partida de malos" : "Duelo individual"); }} style={{
          background: "none", border: "none", padding: 0, margin: 0, cursor: "pointer", display: "block", width: "100%",
          fontFamily: "'Cinzel', serif",
          fontWeight: 900,
          fontSize: 22, letterSpacing: 1.5,
          backgroundImage: "linear-gradient(180deg, #FFEF9F 0%, #FFD700 45%, #B8860B 100%)",
          WebkitBackgroundClip: "text",
          WebkitTextFillColor: "transparent",
          lineHeight: 1.1,
          animation: "neonText 2.2s ease-in-out infinite",
        }}>{roundCycle === 4 ? "UNA PARTIDA DE MALOS" : "DUELO INDIVIDUAL"}</button>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:8, marginTop:6 }}>
          <div style={{ height:1, width:24, background:"linear-gradient(90deg, transparent, #FFD700)" }}/>
          <span style={{ fontFamily:"'Orbitron', sans-serif", fontSize:12, letterSpacing:3, color:"#aaa", fontWeight:700 }}>
            META: <span style={{ color:"#FFD700" }}>{meta}</span> PTS
          </span>
          <div style={{ height:1, width:24, background:"linear-gradient(90deg, #FFD700, transparent)" }}/>
        </div>
      </div>

      {/* ── WINNER BANNER ─────────────────────── */}
      {winner !== null && (
        <div style={{
          background: "#0a0a0a",
          border: "1px solid #FFD700",
          borderRadius: 18, padding: "18px",
          marginBottom: 12, textAlign: "center",
          animation: "comicPop 0.5s ease forwards",
          boxShadow: "0 0 24px #FFD70055, inset 0 0 16px #00000099",
          position: "relative", zIndex: 2,
        }}>
          <div style={{ fontSize: 56, animation: "bounce 0.6s ease infinite" }}>🏆</div>
          <div style={{ fontFamily:"'Cinzel', serif", fontWeight:900, fontSize: 28, color: "#FFD700", letterSpacing:2, textShadow:"0 0 16px #FFD700aa", animation:"neonText 2.2s ease-in-out infinite" }}>
            {names[winner]} GANÓ
          </div>
          <div style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize:22, color:"#fff", letterSpacing:2, marginBottom:10 }}>
            {scores[winner]} PUNTOS
          </div>
          {loserScore === 0 && (
            <div style={{ position:"relative", marginBottom: 10 }}>
              <div style={{ fontSize: 44, animation: "shoeDrop 0.6s ease-out, shoeShake 0.35s ease-in-out infinite 0.6s" }}>👟</div>
              <div style={{
                fontFamily:"'Orbitron', sans-serif", fontSize:14, color:"#fff", letterSpacing:1, marginTop:6,
                background: "#E8000D", display:"inline-block", padding:"8px 14px", borderRadius:8,
                border:"1px solid #ff5555", boxShadow:"0 0 14px #E8000D88",
                animation:"pulse 0.6s ease-in-out infinite",
              }}>
                👟 {names[winner === 0 ? 1 : 0].toUpperCase()} — A PAGAR LAS CERVEZAS!
              </div>
            </div>
          )}
          <div style={{ display:"flex", gap:8, justifyContent:"center", flexWrap:"wrap" }}>
            <button onClick={() => { playClick(); handleReset(); }} style={{
              background: "linear-gradient(180deg, #7CFF8F 0%, #00B800 50%, #006B00 100%)",
              color: "#000",
              border: "none", borderRadius: 999,
              padding: "10px 18px", fontFamily:"'Orbitron', sans-serif",
              fontWeight:900, fontSize: 13, letterSpacing: 1.5, cursor: "pointer",
              boxShadow: "0 0 10px #00B80088",
            }}>🆕 NUEVA PARTIDA</button>
            <button onClick={() => { playClick(); handleRevanche(); }} style={{
              background: "linear-gradient(180deg, #FFEF9F 0%, #FFD700 50%, #B8860B 100%)",
              color: "#000",
              border: "none", borderRadius: 999,
              padding: "10px 18px", fontFamily:"'Orbitron', sans-serif",
              fontWeight:900, fontSize: 13, letterSpacing: 1.5, cursor: "pointer",
              boxShadow: "0 0 10px #FFD70088",
            }}>⚡ REVANCHA</button>
            <button onClick={handleShareResult} style={{
              background: "linear-gradient(180deg, #4dd9ff 0%, #0057D9 50%, #00357d 100%)",
              color: "#fff",
              border: "none", borderRadius: 999,
              padding: "10px 18px", fontFamily:"'Orbitron', sans-serif",
              fontWeight:900, fontSize: 13, letterSpacing: 1.5, cursor: "pointer",
              boxShadow: "0 0 10px #0057D988",
            }}>📲 COMPARTIR</button>
          </div>
        </div>
      )}

      {/* ── SCORE CARDS ───────────────────────── */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10, position:"relative", zIndex:2 }}>
        {[0, 1].map(i => (
          <div key={i} style={{
            background: tc[i].bg,
            border: `1px solid ${tc[i].main}`,
            borderRadius: 14, padding: "10px 8px 10px",
            display: "flex", flexDirection: "column",
            boxShadow: `0 0 16px ${tc[i].main}44, inset 0 0 14px #00000099`,
            position: "relative", overflow: "hidden",
          }}>
            {/* Team name tag */}
            <div style={{
              background: `linear-gradient(180deg, ${tc[i].main}ee 0%, ${tc[i].main} 60%, ${tc[i].main}cc 100%)`,
              border: `1px solid ${tc[i].main}`,
              borderRadius: 8, padding: "6px 6px",
              marginBottom: 4, textAlign: "center",
              boxShadow: `0 0 14px ${tc[i].main}88`,
              position: "relative",
            }}>
              <div style={{
                fontFamily:"'Orbitron', sans-serif",
                fontWeight: 700,
                fontSize: 14, letterSpacing: 1,
                color: "#000",
                textTransform: "uppercase",
                overflow:"hidden", whiteSpace:"nowrap", textOverflow:"ellipsis",
              }}>
                {names[i]}
              </div>
            </div>

            {/* Score number */}
            <div style={{ background: "#050505", border:`1px solid ${tc[i].main}`, borderRadius:10, marginBottom:6, boxShadow:`inset 0 0 14px #00000099, 0 0 10px ${tc[i].main}33`, display:"flex", alignItems:"center", justifyContent:"center", height:90 }}>
              <SlotNumber value={scores[i]} color={tc[i].main} />
            </div>

            {/* Progress bar */}
            <div style={{ marginBottom: 6 }}>
              <div style={{ height: 12, background: "#050505", borderRadius: 99, overflow: "hidden", border:`1px solid ${tc[i].main}55` }}>
                <div style={{
                  height: "100%", borderRadius: 99,
                  width: Math.min((scores[i] / meta) * 100, 100) + "%",
                  background: tc[i].main,
                  boxShadow: `0 0 10px ${tc[i].main}`,
                  transition: "width 0.5s ease",
                }} />
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", marginTop: 2 }}>
                <span style={{ fontSize: 9, fontFamily:"'Orbitron', sans-serif", color: "#666", letterSpacing:1 }}>0</span>
                <span style={{ fontSize: 9, fontFamily:"'Orbitron', sans-serif", color: "#666", letterSpacing:1 }}>{meta}</span>
              </div>
            </div>

            {/* Round history */}
            <div style={{ background: "#050505", border:`1px solid ${tc[i].main}33`, borderRadius: 10, padding: "5px 6px", minHeight: 44, marginBottom: 6 }}>
              {history.length === 0 ? (
                <div style={{ color: "#555", fontSize: 10, textAlign: "center", padding: "6px 0", fontFamily:"'Orbitron', sans-serif", letterSpacing:1 }}>-- SIN RONDAS --</div>
              ) : (
                history.map((r, idx) => {
                  const runningTotal = history.slice(0, idx + 1).reduce((sum, rr) => sum + (rr.tie ? 0 : rr.added[i]), 0);
                  return (
                    <div key={idx}>
                      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "3px 0" }}>
                        <span style={{ fontSize: 12, fontFamily:"'Orbitron', sans-serif", color: "#666", letterSpacing:1, minWidth: 22 }}>J{r.round}</span>
                        <span style={{
                          background: r.tie ? "#1a1a1a" : "#000",
                          color: r.tie ? "#666" : tc[i].main,
                          fontWeight: 700, borderRadius: 6, padding: "2px 7px", fontSize: 12,
                          fontFamily:"'Orbitron', sans-serif", letterSpacing:1,
                          textDecoration: r.tie ? "line-through" : "none",
                          border: `1px solid ${r.tie ? "#333" : tc[i].main}`,
                          minWidth: 34, textAlign: "center",
                        }}>
                          {r.tie ? r.added[i] : r.added[i] > 0 ? "+" + r.added[i] : "-"}
                        </span>
                        <span style={{ fontSize: 14, fontWeight: 700, fontFamily:"'Orbitron', sans-serif", color: tc[i].main, minWidth: 24, textAlign: "right" }}>
                          {runningTotal}
                        </span>
                      </div>
                      {idx < history.length - 1 && <div style={{ height: 1, background: "#1a1a1a" }} />}
                    </div>
                  );
                })
              )}
            </div>

            {/* Input */}
            <input type="number" min="0" placeholder="000"
              value={inputs[i]}
              onChange={e => setInputs(inputs.map((v, idx) => idx === i ? e.target.value : v))}
              onKeyDown={e => e.key === "Enter" && addPoints(i)}
              disabled={winner !== null}
              style={{
                width: "100%", padding: "4px 0 16px 0",
                border: `1px solid ${tc[i].main}`, borderRadius: 10,
                fontSize: 32, textAlign: "center",
                color: tc[i].main, fontWeight: 700,
                background: "#050505", marginBottom: 6,
                boxSizing: "border-box",
                fontFamily: "'Orbitron', sans-serif",
                letterSpacing: 1,
                boxShadow: `inset 0 0 10px #00000099, 0 0 8px ${tc[i].main}44`,
                height: 60,
              }}
            />

            {/* Add button */}
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize: 10, color: "#666", letterSpacing: 1, lineHeight: 1.3 }}>
                {history.length}<br />RND
              </div>
              <button onClick={() => { playClick(); addPoints(i); }} disabled={winner !== null} className="add-btn" style={{
                background: tc[i].main,
                border: "none",
                borderRadius: 10,
                padding: "8px 16px",
                fontFamily:"'Orbitron', sans-serif",
                fontWeight: 900,
                fontSize: 15, letterSpacing: 2, color: "#000",
                cursor: "pointer",
                opacity: winner !== null ? 0.3 : 1,
                boxShadow: `0 0 12px ${tc[i].main}aa`,
              }}>+ SUMAR</button>
            </div>
          </div>
        ))}
      </div>

      {/* ── VA GANANDO ─────────────────────────── */}
      {leadInfo.idx !== -1 && winner === null && (
        <div style={{
          background: "#0a0a0a",
          border: `1px solid ${tc[leadInfo.idx].main}`,
          borderRadius: 999, padding: "10px 18px", marginBottom: 10,
          display: "flex", alignItems: "center", justifyContent: "space-between",
          boxShadow: `0 0 16px ${tc[leadInfo.idx].main}55`,
          animation: "pulse 1s ease infinite",
          position: "relative", zIndex: 2,
        }}>
          <span style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize: 13, letterSpacing: 1, color: "#FFD700" }}>⚡ VA GANANDO</span>
          <span style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize: 14, color: tc[leadInfo.idx].main, textShadow:`0 0 8px ${tc[leadInfo.idx].main}` }}>
            {names[leadInfo.idx]}
          </span>
          <span style={{ background: tc[leadInfo.idx].main, color: "#000", borderRadius: 999, padding: "5px 12px", fontSize: 14, fontFamily:"'Orbitron', sans-serif", fontWeight:900 }}>
            +{leadInfo.diff} PTS
          </span>
        </div>
      )}

      {/* ── TIE + UNDO BUTTONS ─────────────────── */}
      <div style={{ display:"flex", gap:8, marginBottom:10, position:"relative", zIndex:2 }}>
        <button onClick={() => { playClick(); registerTie(); }} disabled={winner !== null} style={{
          flex: 1,
          background: "linear-gradient(180deg, #c77dff 0%, #9B00D9 60%, #5a0080 100%)",
          border: "none",
          borderRadius: 999, padding: "12px 0",
          fontFamily:"'Orbitron', sans-serif",
          fontWeight: 700,
          fontSize: 14, letterSpacing: 1, color: "#fff",
          cursor: "pointer",
          opacity: winner !== null ? 0.3 : 1,
          boxShadow: "0 0 12px #9B00D988",
        }}>🤝 EMPATE</button>

        <button onClick={handleUndo} disabled={winner !== null || history.length === 0} style={{
          flex: 1,
          background: "linear-gradient(180deg, #ff6b6b 0%, #6B0F1A 60%, #3a0810 100%)",
          border: "none",
          borderRadius: 999, padding: "12px 0",
          fontFamily:"'Orbitron', sans-serif",
          fontWeight: 700,
          fontSize: 14, letterSpacing: 1, color: "#fff",
          cursor: "pointer",
          opacity: winner !== null || history.length === 0 ? 0.3 : 1,
          boxShadow: "0 0 12px #6B0F1A88",
        }}>↩️ REVERTIR</button>
      </div>

      {/* ── ASK PLAYER BUTTON ───────────────────── */}
      <button onClick={handleAskPlayer} disabled={history.length === 0} style={{
        width: "100%",
        background: "linear-gradient(180deg, #ffe066 0%, #FFD700 60%, #b8860b 100%)",
        border: "none",
        borderRadius: 999, padding: "11px 0",
        fontFamily:"'Orbitron', sans-serif",
        fontWeight: 700,
        fontSize: 13, letterSpacing: 1, color: "#000",
        cursor: "pointer", marginBottom: 10,
        opacity: history.length === 0 ? 0.3 : 1,
        boxShadow: "0 0 12px #FFD70088",
        position: "relative", zIndex: 2,
      }}>🎙️ ¿QUIÉN SALE?</button>

      {/* ── SHARE IMAGE MODAL ───────────────────── */}
      {shareImageUrl && (
        <div style={{
          position: "fixed", inset: 0, zIndex: 200,
          background: "rgba(0,0,0,0.92)",
          display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
          padding: "20px",
        }} onClick={() => { setShareImageUrl(null); }}>
          <div style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize:14, color:"#FFD700", letterSpacing:1, marginBottom:14, textAlign:"center" }}>
            📲 MANTÉN PRESIONADA LA IMAGEN<br/>PARA GUARDARLA Y COMPARTIRLA
          </div>
          <img src={shareImageUrl} alt="Resultado" onClick={e => e.stopPropagation()} style={{
            maxWidth: "92%", maxHeight: "70vh",
            borderRadius: 16, border: "2px solid #FFD700",
            boxShadow: "0 0 30px #FFD70066",
          }} />
          <button onClick={() => { setShareImageUrl(null); }} style={{
            marginTop: 18,
            background: "#E8000D", border:"none",
            borderRadius:999, padding:"10px 28px",
            fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize:13, letterSpacing:1,
            color:"#fff", cursor:"pointer", boxShadow:"0 0 10px #E8000D88",
          }}>CERRAR</button>
        </div>
      )}

      {/* ── HISTORIAL MODAL ─────────────────────── */}
      {showHistory && (
        <div style={{
          position: "fixed", inset: 0, zIndex: 100,
          background: "rgba(0,0,0,0.85)",
          display: "flex", alignItems: "flex-end",
        }} onClick={() => setShowHistory(false)}>
          <div onClick={e => e.stopPropagation()} style={{
            width: "100%", maxHeight: "75vh",
            background: "#0a0a0a",
            border: "1px solid #FFD700",
            borderRadius: "24px 24px 0 0",
            padding: "16px 16px 32px",
            boxShadow: "0 -8px 30px #FFD70033",
            overflowY: "auto",
          }}>
            {/* Header */}
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:14 }}>
              <div style={{ fontFamily:"'Cinzel', serif", fontWeight:900, fontSize:20, letterSpacing:1.5, color:"#FFD700", textShadow:"0 0 10px #FFD70099" }}>
                🏆 HISTORIAL DE PARTIDAS
              </div>
              <button onClick={() => { playClick(); setShowHistory(false); }} style={{
                background: "#E8000D", border:"none",
                borderRadius:999, width:34, height:34,
                fontFamily:"'Orbitron', sans-serif", fontSize:16, color:"#fff",
                cursor:"pointer", boxShadow:"0 0 10px #E8000D88",
              }}>✕</button>
            </div>

            {/* Resumen ganadas */}
            {matchHistory.length > 0 && (
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:14 }}>
                {[0,1].map(i => {
                  const wins = matchHistory.filter(m => m.winner === names[i]).length;
                  const losses = matchHistory.filter(m => m.loser === names[i]).length;
                  return (
                    <div key={i} style={{
                      background: "#050505", border:`1px solid ${tc[i].main}`,
                      borderRadius:14, padding:"10px 8px", textAlign:"center",
                      boxShadow:`0 0 12px ${tc[i].main}44`,
                    }}>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize:13, color:tc[i].main, letterSpacing:1 }}>{names[i]}</div>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:900, fontSize:26, color:"#00B800", marginTop:2 }}>{wins}</div>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize:10, color:"#666", letterSpacing:1 }}>GANADAS</div>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:900, fontSize:18, color:"#E8000D", marginTop:4 }}>{losses}</div>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize:10, color:"#666", letterSpacing:1 }}>PERDIDAS</div>
                    </div>
                  );
                })}
              </div>
            )}

            {/* Lista de partidas */}
            {matchHistory.length === 0 ? (
              <div style={{ textAlign:"center", fontFamily:"'Orbitron', sans-serif", fontSize:14, color:"#555", padding:"24px 0" }}>
                Aún no hay partidas registradas
              </div>
            ) : (
              matchHistory.map((m, idx) => (
                <div key={idx} style={{
                  background: "#050505",
                  border: "1px solid #333",
                  borderRadius: 14, padding: "10px 12px",
                  marginBottom: 8,
                }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                    <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize:10, color:"#666", letterSpacing:1 }}>
                      PARTIDA {idx + 1} · {m.date}
                    </div>
                    {m.zapato && <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize:10, color:"#E8000D", letterSpacing:1 }}>👟 ZAPATO</div>}
                  </div>
                  <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginTop:6 }}>
                    {/* Ganador */}
                    <div style={{ textAlign:"center", flex:1 }}>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize:9, color:"#00B800", letterSpacing:1 }}>🏆 GANÓ</div>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize:14, color:"#fff" }}>{m.winner}</div>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize:20, color:"#00B800" }}>{m.winScore}</div>
                    </div>
                    <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize:16, color:"#444", padding:"0 8px" }}>VS</div>
                    {/* Perdedor */}
                    <div style={{ textAlign:"center", flex:1 }}>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize:9, color:"#E8000D", letterSpacing:1 }}>💀 PERDIÓ</div>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize:14, color:"#fff" }}>{m.loser}</div>
                      <div style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize:20, color:"#E8000D" }}>{m.loseScore}</div>
                    </div>
                  </div>
                </div>
              ))
            )}

            {/* Botón limpiar historial */}
            {matchHistory.length > 0 && (
              <button onClick={() => {
                setMatchHistory([]);
                try { localStorage.removeItem("losmalucos-matches"); } catch(e) {}
              }} style={{
                width:"100%", marginTop:8,
                background:"#1a1a1a", border:"1px solid #444",
                borderRadius:999, padding:"10px 0",
                fontFamily:"'Orbitron', sans-serif", fontSize:12, letterSpacing:2,
                color:"#888", cursor:"pointer",
              }}>🗑 BORRAR HISTORIAL</button>
            )}
          </div>
        </div>
      )}

      {/* ── BOTTOM BUTTONS ─────────────────────── */}
      <div style={{ display: "flex", gap: 10, marginBottom: 14, position:"relative", zIndex:2 }}>
        <button onClick={() => { playClick(); setShowHistory(true); }} style={{
          flex: 1,
          background: "linear-gradient(180deg, #ffb366 0%, #FF6B00 60%, #a04500 100%)",
          border: "none",
          color: "#000", padding: "12px 0", borderRadius: 999,
          fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize: 14, letterSpacing: 1,
          boxShadow: "0 0 12px #FF6B0088", cursor:"pointer",
        }}>HISTORIAL ({history.length})</button>
        <button onClick={() => { playClick(); handleReset(); }} style={{
          flex: 1,
          background: "linear-gradient(180deg, #7CFF8F 0%, #00B800 60%, #006B00 100%)",
          border: "none",
          color: "#000", padding: "12px 0", borderRadius: 999,
          fontFamily:"'Orbitron', sans-serif", fontWeight:900, fontSize: 14, letterSpacing: 1,
          cursor: "pointer",
          boxShadow: "0 0 12px #00B80088",
        }}>NUEVA PARTIDA</button>
      </div>

      {/* ── HOUSE RULES ────────────────────────── */}
      <div style={{
        background: "#0a0a0a",
        border: "1px solid #FFD700",
        borderRadius: 16, padding: "14px",
        boxShadow: "0 0 16px #FFD70033, inset 0 0 14px #00000099",
        position: "relative", zIndex: 2,
        overflow: "hidden",
      }}>
        <div style={{ fontFamily: "'Cinzel', serif", fontWeight:900, fontSize: 16, color: "#FFD700", textAlign: "center", marginBottom: 10, letterSpacing:1.5, textShadow:"0 0 10px #FFD70099" }}>
          📜 REGLAS DE LA CASA
        </div>
        {[
          { icon:"🙅🏻", text:"No se vale jugar con señas ni meter cabras" },
          { icon:"🍺", text:"El que pierda brinda las cervezas" },
          { icon:"👟", text:"El zapato vale doble" },
        ].map((r, i) => (
          <div key={i} style={{
            fontFamily: "'Orbitron', sans-serif",
            fontSize: "3.2vw", color: "#ccc",
            padding: "8px 4px",
            borderBottom: i < 2 ? "1px dashed #333" : "none",
            lineHeight: 1.4, letterSpacing:0.5,
          }}>
            {r.icon} {r.text}
          </div>
        ))}
      </div>
    </div>
  );
}

function GameMultiScreen({ playerNames, meta, onReset, onRevanche, isRevancha = false }) {
  const n = playerNames.length;
  const [scores, setScores] = useState(Array(n).fill(isRevancha ? 99 : 0));
  const [inputs, setInputs] = useState(Array(n).fill(""));
  const [history, setHistory] = useState([]);
  const [winner, setWinner] = useState(null);
  const [showConfetti, setShowConfetti] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [matchHistory, setMatchHistory] = useState(() => {
    try { return JSON.parse(localStorage.getItem("losmalucos-matches-multi") || "[]"); } catch(e) { return []; }
  });

  // Trigger slot animation only on revancha
  useEffect(() => {
    if (!isRevancha) return;
    const t = setTimeout(() => setScores(Array(n).fill(0)), 120);
    return () => clearTimeout(t);
  }, []);

  const tc = TEAM_COLORS;
  const names = playerNames;

  const speak = (text) => {
    elevenSpeak(text).then((ok) => {
      if (ok) return;
      if (announcerSettings.muted) return;
      if (!window.speechSynthesis) return;
      window.speechSynthesis.cancel();
      setTimeout(() => {
        const utter = new SpeechSynthesisUtterance(text);
        utter.lang = "es-MX"; utter.rate = 0.88; utter.pitch = 0.5; utter.volume = announcerSettings.volume / 100;
        const go = () => {
          const voices = window.speechSynthesis.getVoices();
          const male = voices.find(v => v.lang.startsWith("es") && v.name.toLowerCase().includes("jorge"))
            || voices.find(v => v.lang === "es-MX") || voices.find(v => v.lang.startsWith("es"));
          if (male) utter.voice = male;
          window.speechSynthesis.speak(utter);
        };
        if (window.speechSynthesis.getVoices().length > 0) go();
        else window.speechSynthesis.onvoiceschanged = go;
      }, 150);
    });
  };

  const speakSequence = (texts) => {
    if (announcerSettings.muted) return;
    if (!window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const queue = [...texts];
    // Une todas las frases en un solo pedido a ElevenLabs para que salga
    // como un audio continuo, sin pausas entre frase y frase.
    const combined = queue.filter(Boolean).join(". ");
    elevenSpeak(combined).then((ok) => {
      if (ok) return;
      // Respaldo: voz nativa del navegador, frase por frase
      const fallbackQueue = [...texts];
      const speakNext = () => {
        const text = fallbackQueue.shift();
        if (!text) return;
        const utter = new SpeechSynthesisUtterance(text);
        utter.lang = "es-MX"; utter.rate = 0.88; utter.pitch = 0.5; utter.volume = announcerSettings.volume / 100;
        const voices = window.speechSynthesis.getVoices();
        const male = voices.find(v => v.lang.startsWith("es") && v.name.toLowerCase().includes("jorge"))
          || voices.find(v => v.lang === "es-MX") || voices.find(v => v.lang.startsWith("es"));
        if (male) utter.voice = male;
        utter.onend = () => speakNext();
        utter.onerror = () => speakNext();
        window.speechSynthesis.speak(utter);
      };
      setTimeout(() => {
        if (window.speechSynthesis.getVoices().length > 0) speakNext();
        else window.speechSynthesis.onvoiceschanged = speakNext;
      }, 150);
    });
  };

  const playClick = () => {
    if (announcerSettings.muted) return;
    try {
      const ctx = getAudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "square";
      osc.frequency.setValueAtTime(600 + Math.random() * 200, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.05);
      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.06);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(ctx.currentTime); osc.stop(ctx.currentTime + 0.06);
    } catch(e) {}
  };

  const playSound = (type) => {
    if (announcerSettings.muted) return;
    try {
      const ctx = getAudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      if (type === "point") {
        osc.frequency.setValueAtTime(520, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(780, ctx.currentTime + 0.12);
        gain.gain.setValueAtTime(0.3, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.2);
        osc.start(); osc.stop(ctx.currentTime + 0.2);
      } else if (type === "win") {
        [520, 660, 780, 1040].forEach((freq, idx) => {
          const o = ctx.createOscillator(); const g = ctx.createGain();
          o.connect(g); g.connect(ctx.destination);
          o.frequency.value = freq;
          g.gain.setValueAtTime(0.25, ctx.currentTime + idx * 0.12);
          g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.12 + 0.25);
          o.start(ctx.currentTime + idx * 0.12); o.stop(ctx.currentTime + idx * 0.12 + 0.25);
        });
      }
    } catch(e) {}
  };

  const addPoints = (i) => {
    const pts = parseInt(inputs[i]);
    if (isNaN(pts) || pts <= 0) return;
    unlockAudioTap();
    const newScores = scores.map((s, idx) => idx === i ? s + pts : s);
    const roundsPlayed = history.length;
    setHistory([...history, { round: (roundsPlayed % n) + 1, playerIdx: i, added: pts, tie: false }]);
    const newWinner = newScores[i] >= meta ? i : null;
    setScores(newScores);
    setInputs(Array(n).fill(""));
    playSound("point");
    if (newWinner !== null) {
      setWinner(newWinner);
      setShowConfetti(true);
      playSound("win");
      const ranking = newScores.map((s, idx) => ({ idx, s })).sort((a, b) => b.s - a.s);

      // Zapato: jugadores que quedaron en 0
      const zapateros = names.filter((_, idx) => idx !== newWinner && newScores[idx] === 0);

      // "Detrás de la ambulancia": solo modo 4 jugadores, y solo si NO hubo zapato en esta partida.
      // Si alguien se llevó el zapato, la ambulancia no se anuncia para nadie.
      let ambulancia = [];
      if (n === 4 && zapateros.length === 0) {
        const puntajesConAnotacion = newScores.filter((s, idx) => idx !== newWinner && s > 0);
        if (puntajesConAnotacion.length > 0) {
          const minScore = Math.min(...puntajesConAnotacion);
          ambulancia = names.filter((_, idx) => idx !== newWinner && newScores[idx] === minScore);
        }
      }

      const newMatch = {
        date: new Date().toLocaleDateString("es-VE"),
        ranking: ranking.map(r => ({ name: names[r.idx], score: r.s })),
        zapateros,
        ambulancia,
      };
      const updated = [...matchHistory, newMatch];
      setMatchHistory(updated);
      try { localStorage.setItem("losmalucos-matches-multi", JSON.stringify(updated)); } catch(e) {}
      const frasesGanar = [
        `Llego el campeon! ${names[newWinner]} gano la partida con ${newScores[newWinner]} puntos. Felicitaciones`,
        `Asi si es jugar domino! ${names[newWinner]} se corono con ${newScores[newWinner]} puntos`,
      ];
      const secuenciaFinal = [frasesGanar[Math.floor(Math.random() * frasesGanar.length)]];

      if (zapateros.length === 1) {
        secuenciaFinal.push(`${zapateros[0]} se llevo el zapato. Cero puntos! Que malo! Le toca brindar las cervezas`);
      } else if (zapateros.length > 1) {
        secuenciaFinal.push(`${zapateros.join(" y ")} se llevaron el zapato. Cero puntos! Que malos! Les toca brindar las cervezas`);
      }

      if (ambulancia.length === 1) {
        secuenciaFinal.push(`${ambulancia[0]} llego detras de la ambulancia`);
      } else if (ambulancia.length > 1) {
        secuenciaFinal.push(`${ambulancia.join(" y ")} llegaron detras de la ambulancia`);
      }

      setTimeout(() => speakSequence(secuenciaFinal), 600);
    } else {
      const nextIdx = (roundsPlayed + 1) % n;
      const eraPrimero = scores[i] === 0 && history.some(r => !r.tie && r.playerIdx !== i);
      const secuencia = [];

      if (eraPrimero) {
        const rompeHielo = [
          `${names[i]} le puso el numero a la casa`,
          `${names[i]} rayó`,
        ];
        secuencia.push(rompeHielo[Math.floor(Math.random() * rompeHielo.length)]);
      }

      const frasesIndividual = pts <= 5 ? [
        `Es mejor coger ${pts} que ${pts} cojan a uno. ${names[i]} anoto ${pts} puntos`,
        `Algo es algo. ${names[i]} se llevo ${pts} puntitos`,
      ] : [
        `Muy bien! ${names[i]} anoto ${pts} puntos. Acumulo ${newScores[i]} en total`,
        `Asi se juega! ${names[i]} se llevo ${pts} puntos. Lleva ${newScores[i]} acumulado`,
        `Ahi esta! ${names[i]} se apunto ${pts} punticos. Total acumulado ${newScores[i]}`,
        `${names[i]} suma ${pts}. Acumulo ${newScores[i]} puntos`,
      ];
      secuencia.push(frasesIndividual[Math.floor(Math.random() * frasesIndividual.length)]);

      // Anunciar una sola vez si algún jugador está a 5 puntos o menos de ganar
      const cercaDeMeta = newScores.some((s) => {
        const restante = meta - s;
        return restante <= 5 && restante > 0;
      });
      if (cercaDeMeta) {
        secuencia.push("Todavía no se va");
      }

      // Se dice solo cuando TODOS los jugadores están a 5 puntos o menos de ganar
      const todosCercaDeMeta = newScores.every((s) => {
        const restante = meta - s;
        return restante <= 10 && restante > 0;
      });
      if (todosCercaDeMeta) {
        secuencia.push("Aqui cualquier culo echa sangre");
      }

      secuencia.push(`Sale ${names[nextIdx]}`);

      setTimeout(() => speakSequence(secuencia), 800);
    }
  };

  const registerTie = () => {
    const roundsPlayed = history.length;
    setHistory([...history, { round: (roundsPlayed % n) + 1, added: Array(n).fill(0), tie: true }]);
    setInputs(Array(n).fill(""));
    playSound("tie");
    speak("Empate en la ronda, nadie suma");
  };

  const handleAskPlayer = () => {
    playClick();
    if (history.length === 0) { speak("Todavia no ha salido nadie"); return; }
    const nextIdx = history.length % n;
    speak(`Sale ${names[nextIdx]}`);
  };

  const handleUndo = () => {
    if (history.length === 0 || winner !== null) return;
    const last = history[history.length - 1];
    const prevScores = last.tie
      ? scores.map((s, idx) => s - last.added[idx])
      : scores.map((s, idx) => idx === last.playerIdx ? s - last.added : s);
    setScores(prevScores);
    setHistory(history.slice(0, -1));
    playClick();
    speak("Espera, vamos a revertir ese punto");
  };

  const handleReset = () => { onReset(); };
  const handleRevanche = () => {
    speak("Vamos por la revancha muchachos");
    onRevanche();
  };

  const sortedRanking = scores.map((s, i) => ({ i, s })).sort((a, b) => b.s - a.s);

  return (
    <div style={{
      minHeight: "100vh",
      background: "radial-gradient(ellipse at top, #1a1a1a 0%, #000000 60%)",
      fontFamily: "'Orbitron', sans-serif",
      padding: "14px 14px 100px",
      position: "relative", overflow: "hidden",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700;900&family=Cinzel:wght@600;900&display=swap');
        * { box-sizing: border-box; }
        @keyframes neonText { 0%,100%{ text-shadow: 0 0 8px #FFD700, 0 0 18px #FFD70099, 0 0 32px #FFD70055 } 50%{ text-shadow: 0 0 14px #FFD700, 0 0 28px #FFD700cc, 0 0 48px #FFD70088 } }
        @keyframes bounce { 0%,100%{transform:scale(1) rotate(-5deg)} 50%{transform:scale(1.15) rotate(5deg)} }
        @keyframes pulse { 0%,100%{transform:scale(1)} 50%{transform:scale(1.04)} }
        @keyframes confettiFall { 0%{transform:translateY(-20px) rotate(0deg);opacity:1} 100%{transform:translateY(110vh) rotate(720deg);opacity:0} }
      `}</style>

      {showConfetti && <Confetti />}

      {/* Header */}
      <div style={{
        background: "#0a0a0a", border: "1px solid #FFD700", borderRadius: 14,
        padding: "10px 16px 16px", marginBottom: 12, textAlign: "center",
        boxShadow: "0 0 16px #FFD70044, inset 0 0 14px #00000099",
        position: "relative", zIndex: 2,
      }}>
        <VolumeButton corner="left" />
        <MuteButton corner="right" />
        <button onClick={() => { unlockAudioTap(); speak("Todos contra todos"); }} style={{
          background: "none", border: "none", padding: 0, margin: 0, cursor: "pointer", display: "block", width: "100%",
          fontFamily: "'Cinzel', serif", fontWeight: 900, fontSize: 20, letterSpacing: 1.5,
          backgroundImage: "linear-gradient(180deg, #FFEF9F 0%, #FFD700 45%, #B8860B 100%)",
          WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent",
          animation: "neonText 2.2s ease-in-out infinite",
        }}>TODOS CONTRA TODOS</button>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:8, marginTop:6 }}>
          <span style={{ fontFamily:"'Orbitron', sans-serif", fontSize:12, letterSpacing:3, color:"#aaa", fontWeight:700 }}>
            META: <span style={{ color:"#FFD700" }}>{meta}</span> PTS
          </span>
        </div>
      </div>

      {/* Winner banner */}
      {winner !== null && (
        <div style={{
          background: "#0a0a0a", border: "1px solid #FFD700", borderRadius: 18, padding: "18px",
          marginBottom: 12, textAlign: "center", boxShadow: "0 0 24px #FFD70055, inset 0 0 16px #00000099",
          position: "relative", zIndex: 2,
        }}>
          <div style={{ fontSize: 56, animation: "bounce 0.6s ease infinite" }}>🏆</div>
          <div style={{ fontFamily:"'Cinzel', serif", fontWeight:900, fontSize: 26, color: tc[winner % tc.length].main, letterSpacing:1.5, textShadow:`0 0 12px ${tc[winner % tc.length].main}99` }}>
            {names[winner]} GANÓ
          </div>
          <div style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize:20, color:"#fff", letterSpacing:2, marginBottom:10 }}>
            {scores[winner]} PUNTOS
          </div>
          {scores.some((s, idx) => idx !== winner && s === 0) && (
            <div style={{
              fontFamily:"'Orbitron', sans-serif", fontSize:13, color:"#fff", letterSpacing:1, marginBottom:10,
              background: "#E8000D", display:"inline-block", padding:"8px 14px", borderRadius:8,
              border:"1px solid #ff5555", boxShadow:"0 0 14px #E8000D88",
              animation:"pulse 0.6s ease-in-out infinite",
            }}>
              👟 {scores.map((s, idx) => (idx !== winner && s === 0) ? names[idx] : null).filter(Boolean).join(" y ").toUpperCase()} — ¡ZAPATO!
            </div>
          )}
          <div style={{ display:"flex", gap:8, justifyContent:"center", flexWrap:"wrap" }}>
            <button onClick={() => { playClick(); handleReset(); }} style={{
              background: "linear-gradient(180deg, #7CFF8F 0%, #00B800 50%, #006B00 100%)", color: "#000",
              border: "none", borderRadius: 999, padding: "10px 18px", fontFamily:"'Orbitron', sans-serif",
              fontWeight:900, fontSize: 13, letterSpacing: 1.5, cursor: "pointer", boxShadow: "0 0 10px #00B80088",
            }}>🆕 NUEVA PARTIDA</button>
            <button onClick={() => { playClick(); handleRevanche(); }} style={{
              background: "linear-gradient(180deg, #FFEF9F 0%, #FFD700 50%, #B8860B 100%)", color: "#000",
              border: "none", borderRadius: 999, padding: "10px 18px", fontFamily:"'Orbitron', sans-serif",
              fontWeight:900, fontSize: 13, letterSpacing: 1.5, cursor: "pointer", boxShadow: "0 0 10px #FFD70088",
            }}>⚡ REVANCHA</button>
          </div>
        </div>
      )}

      {/* Tarjetas de jugadores - grid compacto */}
      <div style={{ display: "grid", gridTemplateColumns: n === 3 ? "1fr 1fr 1fr" : "1fr 1fr", gap: 10, marginBottom: 12, position:"relative", zIndex:2 }}>
        {Array.from({ length: n }).map((_, i) => {
          const color = tc[i % tc.length].main;
          const rank = sortedRanking.findIndex(r => r.i === i);
          return (
            <div key={i} style={{
              border: `1px solid ${color}`, borderRadius: 14, padding: n === 3 ? "6px 4px" : "10px 8px",
              background: "#0a0a0a", boxShadow: `0 0 14px ${color}44, inset 0 0 12px #00000099`,
            }}>
              <div style={{
                background: `linear-gradient(180deg, ${color}ee 0%, ${color} 60%, ${color}cc 100%)`,
                borderRadius: 8, padding: "4px 2px", marginBottom: 4, textAlign: "center",
                boxShadow: `0 0 10px ${color}88`,
              }}>
                <div style={{
                  fontFamily:"'Orbitron', sans-serif", fontWeight: 700, fontSize: n === 3 ? 9 : 12, letterSpacing: 0,
                  color: "#000", textTransform: "uppercase",
                  overflow:"hidden", whiteSpace:"nowrap", textOverflow:"ellipsis",
                }}>
                  {names[i]}
                </div>
              </div>

              <div style={{
                background: "#050505", border:`1px solid ${color}`, borderRadius:10, marginBottom:6,
                boxShadow:`inset 0 0 12px #00000099, 0 0 8px ${color}33`,
                display:"flex", alignItems:"center", justifyContent:"center", height: n === 3 ? 70 : 80,
              }}>
                <SlotNumber value={scores[i]} color={color} fontSize={n === 3 ? 44 : 64} />
              </div>

              <div style={{ marginBottom: 6 }}>
                <div style={{ height: 8, background: "#050505", borderRadius: 99, overflow: "hidden", border:`1px solid ${color}44` }}>
                  <div style={{
                    height: "100%", borderRadius: 99,
                    width: Math.min((scores[i] / meta) * 100, 100) + "%",
                    background: color, boxShadow: `0 0 8px ${color}`, transition: "width 0.5s ease",
                  }} />
                </div>
              </div>

              {/* Round history */}
              <div style={{ background: "#050505", border:`1px solid ${color}33`, borderRadius: 10, padding: "5px 6px", minHeight: 44, marginBottom: 6, maxHeight: 110, overflowY: "auto" }}>
                {history.length === 0 ? (
                  <div style={{ color: "#555", fontSize: 9, textAlign: "center", padding: "6px 0", fontFamily:"'Orbitron', sans-serif", letterSpacing:1 }}>SIN RONDAS</div>
                ) : (
                  history.map((r, idx) => {
                    const ptsForThis = r.tie ? r.added[i] : (r.playerIdx === i ? r.added : 0);
                    const runningTotal = history.slice(0, idx + 1).reduce((sum, rr) => {
                      if (rr.tie) return sum + rr.added[i];
                      return sum + (rr.playerIdx === i ? rr.added : 0);
                    }, 0);
                    return (
                      <div key={idx}>
                        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "3px 0" }}>
                          <span style={{ fontSize: 11, fontFamily:"'Orbitron', sans-serif", color: "#666", letterSpacing:1, minWidth: 18 }}>J{r.round}</span>
                          <span style={{
                            background: r.tie ? "#1a1a1a" : "#000",
                            color: r.tie ? "#666" : color,
                            fontWeight: 700, borderRadius: 6, padding: "2px 6px", fontSize: 11,
                            fontFamily:"'Orbitron', sans-serif", letterSpacing:1,
                            textDecoration: r.tie ? "line-through" : "none",
                            border: `1px solid ${r.tie ? "#333" : color}`,
                            minWidth: 30, textAlign: "center",
                          }}>
                            {r.tie ? ptsForThis : ptsForThis > 0 ? "+" + ptsForThis : "-"}
                          </span>
                          <span style={{ fontSize: 12, fontWeight: 700, fontFamily:"'Orbitron', sans-serif", color: color, minWidth: 20, textAlign: "right" }}>
                            {runningTotal}
                          </span>
                        </div>
                        {idx < history.length - 1 && <div style={{ height: 1, background: "#1a1a1a" }} />}
                      </div>
                    );
                  })
                )}
              </div>

              <input type="number" min="0" placeholder="000"
                value={inputs[i]}
                onChange={e => setInputs(inputs.map((v, idx) => idx === i ? e.target.value : v))}
                onKeyDown={e => e.key === "Enter" && addPoints(i)}
                disabled={winner !== null}
                style={{
                  width: "100%", padding: n === 3 ? "2px 0 8px 0" : "4px 0 10px 0",
                  border: `1px solid ${color}`, borderRadius: 8,
                  fontSize: n === 3 ? 18 : 22, textAlign: "center", color: color, fontWeight: 700,
                  background: "#050505", marginBottom: 6, boxSizing: "border-box",
                  fontFamily: "'Orbitron', sans-serif",
                  boxShadow: `inset 0 0 8px #00000099, 0 0 6px ${color}44`,
                  height: n === 3 ? 36 : 42,
                }}
              />

              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
                <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize: n === 3 ? 9 : 10, color: "#666", letterSpacing: 1, lineHeight: 1.3, flexShrink: 0 }}>
                  {history.length}<br />RND
                </div>
                <button onClick={() => { playClick(); addPoints(i); }} disabled={winner !== null} style={{
                  flex: 1, background: color, border: "none", borderRadius: 8,
                  padding: n === 3 ? "6px 0" : "8px 0", fontFamily:"'Orbitron', sans-serif", fontWeight: 900,
                  fontSize: n === 3 ? 11 : 13, letterSpacing: 1, color: "#000", cursor: "pointer",
                  opacity: winner !== null ? 0.3 : 1, boxShadow: `0 0 10px ${color}aa`,
                }}>+ SUMAR</button>
              </div>
            </div>
          );
        })}
      </div>

      {/* Empate + Revertir */}
      <div style={{ display:"flex", gap:8, marginBottom:10, position:"relative", zIndex:2 }}>
        <button onClick={() => { playClick(); registerTie(); }} disabled={winner !== null} style={{
          flex: 1, background: "linear-gradient(180deg, #c77dff 0%, #9B00D9 60%, #5a0080 100%)",
          border: "none", borderRadius: 999, padding: "12px 0", fontFamily:"'Orbitron', sans-serif",
          fontWeight: 700, fontSize: 13, letterSpacing: 1, color: "#fff", cursor: "pointer",
          opacity: winner !== null ? 0.3 : 1, boxShadow: "0 0 12px #9B00D988",
        }}>🤝 EMPATE</button>

        <button onClick={handleUndo} disabled={winner !== null || history.length === 0} style={{
          flex: 1, background: "linear-gradient(180deg, #ff6b6b 0%, #6B0F1A 60%, #3a0810 100%)",
          border: "none", borderRadius: 999, padding: "12px 0", fontFamily:"'Orbitron', sans-serif",
          fontWeight: 700, fontSize: 13, letterSpacing: 1, color: "#fff", cursor: "pointer",
          opacity: winner !== null || history.length === 0 ? 0.3 : 1, boxShadow: "0 0 12px #6B0F1A88",
        }}>↩️ REVERTIR</button>
      </div>

      {/* Quién sale */}
      <button onClick={handleAskPlayer} disabled={history.length === 0} style={{
        width: "100%", background: "linear-gradient(180deg, #ffe066 0%, #FFD700 60%, #b8860b 100%)",
        border: "none", borderRadius: 999, padding: "12px 0", fontFamily:"'Orbitron', sans-serif",
        fontWeight: 700, fontSize: 14, letterSpacing: 1, color: "#000", cursor: "pointer",
        opacity: history.length === 0 ? 0.3 : 1, boxShadow: "0 0 12px #FFD70088",
        marginBottom: 12, position:"relative", zIndex:2,
      }}>🎙️ ¿QUIÉN SALE?</button>

      {/* Historial + Nueva Partida */}
      <div style={{ display: "flex", gap: 10, position:"relative", zIndex:2, marginBottom: 12 }}>
        <button onClick={() => { playClick(); setShowHistory(true); }} style={{
          flex: 1, background: "linear-gradient(180deg, #ffb366 0%, #FF6B00 60%, #a04500 100%)",
          border: "none", color: "#000", padding: "12px 0", borderRadius: 999,
          fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize: 14, letterSpacing: 1,
          boxShadow: "0 0 12px #FF6B0088", cursor:"pointer",
        }}>HISTORIAL ({history.length})</button>
        <button onClick={() => { playClick(); handleReset(); }} style={{
          flex: 1, background: "linear-gradient(180deg, #7CFF8F 0%, #00B800 60%, #006B00 100%)",
          border: "none", color: "#000", padding: "12px 0", borderRadius: 999,
          fontFamily:"'Orbitron', sans-serif", fontWeight:900, fontSize: 14, letterSpacing: 1,
          cursor: "pointer", boxShadow: "0 0 12px #00B80088",
        }}>NUEVA PARTIDA</button>
      </div>

      {/* Tabla de posiciones */}
      <div style={{
        background: "#0a0a0a", border: "1px solid #FFD700", borderRadius: 16, padding: "14px",
        boxShadow: "0 0 16px #FFD70033, inset 0 0 14px #00000099", position: "relative", zIndex: 2, marginBottom: 12,
      }}>
        <div style={{ fontFamily: "'Cinzel', serif", fontWeight:900, fontSize: 16, color: "#FFD700", textAlign: "center", marginBottom: 10, letterSpacing:1.5, textShadow:"0 0 10px #FFD70099" }}>
          📊 TABLA DE POSICIONES
        </div>
        {sortedRanking.map(({ i, s }, rank) => (
          <div key={i} style={{
            display:"flex", justifyContent:"space-between", alignItems:"center",
            padding:"8px 10px", marginBottom: 6, borderRadius: 10,
            background: rank === 0 ? "#FFD70022" : "#050505",
            border: `1px solid ${rank === 0 ? "#FFD700" : "#333"}`,
          }}>
            <span style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize:14, color: tc[i % tc.length].main }}>
              {rank === 0 ? "🥇" : rank === 1 ? "🥈" : rank === 2 ? "🥉" : "🚑"} {names[i]}
            </span>
            <span style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:900, fontSize:16, color: "#FFD700" }}>{s} pts</span>
          </div>
        ))}
      </div>

      {/* Modal de historial */}
      {showHistory && (
        <div style={{
          position: "fixed", inset: 0, zIndex: 100, background: "rgba(0,0,0,0.85)",
          display: "flex", alignItems: "flex-end",
        }} onClick={() => setShowHistory(false)}>
          <div onClick={e => e.stopPropagation()} style={{
            width: "100%", maxHeight: "75vh", background: "#0a0a0a",
            border: "1px solid #FFD700", borderRadius: "24px 24px 0 0",
            padding: "16px 16px 32px", boxShadow: "0 -8px 30px #FFD70033", overflowY: "auto",
          }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:14 }}>
              <div style={{ fontFamily:"'Cinzel', serif", fontWeight:900, fontSize:20, letterSpacing:1.5, color:"#FFD700", textShadow:"0 0 10px #FFD70099" }}>
                🏆 HISTORIAL DE PARTIDAS
              </div>
              <button onClick={() => { playClick(); setShowHistory(false); }} style={{
                background: "#E8000D", border:"none", borderRadius:999, width:34, height:34,
                fontFamily:"'Orbitron', sans-serif", fontSize:16, color:"#fff",
                cursor:"pointer", boxShadow:"0 0 10px #E8000D88",
              }}>✕</button>
            </div>

            {matchHistory.length === 0 ? (
              <div style={{ textAlign:"center", fontFamily:"'Orbitron', sans-serif", fontSize:14, color:"#555", padding:"24px 0" }}>
                Aún no hay partidas registradas
              </div>
            ) : (
              matchHistory.slice().reverse().map((m, idx) => (
                <div key={idx} style={{
                  background: "#050505", border: "1px solid #333", borderRadius: 14,
                  padding: "10px 12px", marginBottom: 8,
                }}>
                  <div style={{ fontFamily:"'Orbitron', sans-serif", fontSize:10, color:"#666", letterSpacing:1, marginBottom:6 }}>
                    PARTIDA {matchHistory.length - idx} · {m.date}
                  </div>
                  {m.ranking.map((r, rIdx) => (
                    <div key={rIdx} style={{ display:"flex", justifyContent:"space-between", padding:"3px 0" }}>
                      <span style={{ fontFamily:"'Orbitron', sans-serif", fontSize:13, color: rIdx === 0 ? "#FFD700" : "#aaa" }}>
                        {rIdx === 0 ? "🥇" : rIdx === 1 ? "🥈" : rIdx === 2 ? "🥉" : "  "} {r.name}
                      </span>
                      <span style={{ fontFamily:"'Orbitron', sans-serif", fontWeight:700, fontSize:13, color: rIdx === 0 ? "#FFD700" : "#aaa" }}>{r.score} pts</span>
                    </div>
                  ))}
                </div>
              ))
            )}

            {matchHistory.length > 0 && (
              <button onClick={() => {
                setMatchHistory([]);
                try { localStorage.removeItem("losmalucos-matches-multi"); } catch(e) {}
              }} style={{
                width:"100%", marginTop:8, background:"#1a1a1a", border:"1px solid #444",
                borderRadius:999, padding:"10px 0", fontFamily:"'Orbitron', sans-serif",
                fontSize:12, letterSpacing:2, color:"#888", cursor:"pointer",
              }}>🗑 BORRAR HISTORIAL</button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

function WelcomeScreen({ onContinue }) {
  const [exiting, setExiting] = useState(false);

  const goNext = () => {
    if (exiting) return;
    setExiting(true);
    setTimeout(() => { onContinue(); }, 320);
  };

  useEffect(() => {
    const timer = setTimeout(() => { goNext(); }, 1400);
    return () => clearTimeout(timer);
  }, []);

  const handleTap = () => {
    if (navigator.vibrate) navigator.vibrate(40);
    goNext();
  };

  return (
    <div style={{
      minHeight: "100vh",
      background: "#000000",
      display: "flex", alignItems: "center", justifyContent: "center",
      position: "relative", overflow: "hidden",
      cursor: "pointer",
    }} onClick={handleTap}>
      <style>{`
        @keyframes splashFade { from{opacity:0; transform:scale(0.92)} to{opacity:1; transform:scale(1)} }
        @keyframes splashZoomOut { from{opacity:1; transform:scale(1)} to{opacity:0; transform:scale(2.4)} }
      `}</style>
      <img src={DOMINO_MENU_BASE64} alt="Domino Venezuela" style={{
        width: "33%", maxWidth: 168,
        height: "auto",
        objectFit: "contain",
        display: "block",
        animation: exiting
          ? "splashZoomOut 0.32s ease-in forwards"
          : "splashFade 0.5s ease-out",
        filter: "drop-shadow(0 0 30px rgba(0,87,217,0.35))",
      }} />
    </div>
  );
}

export default function App() {
  const [game, setGame] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showWelcome, setShowWelcome] = useState(true);
  const [mode, setMode] = useState(null);
  const [revanchaKey, setRevanchaKey] = useState(0);
  const [audioUnlocked, setAudioUnlocked] = useState(false);

  useEffect(() => { setLoading(false); }, []);

  // Desbloquear AudioContext e iOS SpeechSynthesis con el primer toque
  useEffect(() => {
    const unlock = () => {
      if (audioUnlocked) return;
      // Desbloquear AudioContext
      try {
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        const buf = ctx.createBuffer(1, 1, 22050);
        const src = ctx.createBufferSource();
        src.buffer = buf;
        src.connect(ctx.destination);
        src.start(0);
        ctx.resume().then(() => {
          if (_ctx) _ctx.resume();
        });
      } catch(e) {}
      // Desbloquear SpeechSynthesis en iOS
      try {
        const u = new SpeechSynthesisUtterance("");
        u.volume = 0;
        window.speechSynthesis.speak(u);
      } catch(e) {}
      // Desbloquear el reproductor de audio de la voz clonada (ElevenLabs) en iOS,
      // para que hable desde el primer punto de la partida, no solo desde el segundo.
      try {
        const silentAudio = new Audio("data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA=");
        silentAudio.volume = 0;
        silentAudio.play().catch(() => {});
      } catch(e) {}
      setAudioUnlocked(true);
      document.removeEventListener("touchstart", unlock);
      document.removeEventListener("click", unlock);
    };
    document.addEventListener("touchstart", unlock, { passive: true });
    document.addEventListener("click", unlock);
    return () => {
      document.removeEventListener("touchstart", unlock);
      document.removeEventListener("click", unlock);
    };
  }, []);

  if (loading) return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: VINOTINTO }}>
      <div style={{ color: "#FFD700", fontSize: 14, letterSpacing: 2, fontWeight: 700 }}>CARGANDO...</div>
    </div>
  );

  if (showWelcome) return <WelcomeScreen onContinue={() => setShowWelcome(false)} />;

  if (!mode) return <ModeMenuScreen onSelectMode={(m) => setMode(m)} />;

  if (mode === "equipos") {
    if (!game) return <SetupScreen onStart={(t1, t2, meta, players) => setGame({ t1, t2, meta, players, resume: null })} onBack={() => setMode(null)} />;
    return (
      <GameScreen
        team1={game.t1} team2={game.t2} meta={game.meta}
        initialState={game.resume}
        players={game.players || ["Jugador 1", "Jugador 2", "Jugador 3", "Jugador 4"]}
        onReset={() => { setGame(null); setMode(null); }}
        onRevanche={() => setGame({ t1: game.t1, t2: game.t2, meta: game.meta, players: game.players, resume: null })}
      />
    );
  }

  if (mode === "1v1") {
    if (!game) return <Setup1v1Screen onStart={(p1, p2, meta) => setGame({ t1: p1, t2: p2, meta, players: [p1, p2], isRevancha: false, resume: null })} onBack={() => setMode(null)} />;
    return (
      <GameScreen
        key={revanchaKey}
        team1={game.t1} team2={game.t2} meta={game.meta}
        initialState={game.resume}
        roundCycle={2}
        players={game.players || [game.t1, game.t2]}
        isRevancha={game.isRevancha || false}
        onReset={() => { setGame(null); setMode(null); }}
        onRevanche={() => { setRevanchaKey(k => k + 1); setGame({ t1: game.t1, t2: game.t2, meta: game.meta, players: game.players, isRevancha: true, resume: null }); }}
      />
    );
  }

  if (mode === "3p") {
    if (!game) return <Setup3pScreen onStart={(names, meta) => setGame({ names, meta, revancha: false })} onBack={() => setMode(null)} />;
    const savedNames3 = game.names;
    const savedMeta3 = game.meta;
    return (
      <GameMultiScreen
        key={revanchaKey}
        playerNames={savedNames3} meta={savedMeta3}
        isRevancha={game.revancha || false}
        onReset={() => { setGame(null); setMode(null); }}
        onRevanche={() => { setRevanchaKey(k => k + 1); setGame({ names: savedNames3, meta: savedMeta3, revancha: true }); }}
      />
    );
  }

  if (mode === "4p") {
    if (!game) return <Setup4pScreen onStart={(names, meta) => setGame({ names, meta, revancha: false })} onBack={() => setMode(null)} />;
    const savedNames4 = game.names;
    const savedMeta4 = game.meta;
    return (
      <GameMultiScreen
        key={revanchaKey}
        playerNames={savedNames4} meta={savedMeta4}
        isRevancha={game.revancha || false}
        onReset={() => { setGame(null); setMode(null); }}
        onRevanche={() => { setRevanchaKey(k => k + 1); setGame({ names: savedNames4, meta: savedMeta4, revancha: true }); }}
      />
    );
  }

  return <ModeMenuScreen onSelectMode={(m) => setMode(m)} />;
}
